function CheckAnswer(Answer)
if isequal(Answer,[1,1,0])
    disp("You are correct.")
elseif isequal(Answer,[0,0,0])
    warning("Select at least one checkbox")
else
    disp("Have you selected all of the linear datasets?")
end
end
